// intent: Verify that BON8 floating-point numbers parse correctly.
#include <nlohmann/json.hpp>
#include <iostream>
#include <vector>

int main() {
    try {
        std::vector<uint8_t> data = {0x01, 0x01, 'a', 0xFA, 0x40, 0x48, 0xF5, 0xC3};
        auto j = nlohmann::json::from_bon8(data);
        std::cout << "bon8 float: " << j.dump(2) << "\n";
    } catch (const std::exception& e) {
        std::cout << "exception: " << e.what() << "\n";
    }
}
